{
  MagickPassFail status = MagickPass;
  char *estr=0;
  *value=strtod(str,&estr);
  if (str == estr)
    {
      *value=0.0;
      status=MagickFail;
    }
#if defined(INFINITY)
  else if ((*value == +INFINITY) || (*value == -INFINITY))
    {
      *value=0.0;
      status=MagickFail;
      errno=ERANGE;
    }
#endif
  else if (isnan(*value))
    {
      *value=0.0;
      status=MagickFail;
      errno=ERANGE;
    }
  return status;
}

